def gcd(a, b):
    # Iterative Euclid; gcd(0, x) = x
    while b:
        a, b = b, a % b
    return a


def maxValidSplits(nums):
    n = len(nums)

    # pre[i] = gcd(nums[0..i]), suf[i] = gcd(nums[i..n-1]), suf[n] = 0
    pre = [0] * n
    g = 0
    for i in range(n):
        g = gcd(g, nums[i])
        pre[i] = g
    suf = [0] * (n + 1)
    g = 0
    for i in range(n - 1, -1, -1):
        g = gcd(g, nums[i])
        suf[i] = g

    # first[v] = first index whose prefix gcd is v; last[v] = last index whose suffix gcd is v
    first = {}
    for i in range(n):
        if pre[i] not in first:
            first[pre[i]] = i
    last = {}
    for j in range(n - 1, -1, -1):
        if suf[j] not in last:
            last[suf[j]] = j

    # a_at[x]: first index (in the array after removing x) where the prefix gcd equals the final gcd
    a_at = [0] * n
    # chain = [(gcd of nums[s..i], first i reaching it)] for the start s = x + 1
    chain = []
    for x in range(n - 1, -1, -1):
        L = pre[x - 1] if x > 0 else 0
        R = suf[x + 1]
        G = gcd(L, R)
        if x > 0 and L == G:
            # The prefix before x already reaches G
            a_at[x] = first[L]
        else:
            # Find the first index after x where combining with L reaches G
            for v, i in chain:
                if gcd(L, v) == G:
                    a_at[x] = i - 1  # shift down by one because x is removed
                    break
        # Extend the chain from start x + 1 to start x, merging equal gcd values
        new_chain = [(nums[x], x)]
        for v, i in chain:
            nv = gcd(nums[x], v)
            if nv != new_chain[-1][0]:
                new_chain.append((nv, i))
        chain = new_chain

    # b_at[x]: last index (in the array after removing x) where the suffix gcd equals the final gcd
    b_at = [0] * n
    # chain = [(gcd of nums[j..e], largest j reaching it)] for the end e = x - 1
    chain = []
    for x in range(n):
        L = pre[x - 1] if x > 0 else 0
        R = suf[x + 1]
        G = gcd(L, R)
        if x < n - 1 and R == G:
            # The suffix after x already reaches G
            b_at[x] = last[R] - 1  # shift down by one because x is removed
        else:
            # Find the last index before x where combining with R reaches G
            for v, j in chain:
                if gcd(R, v) == G:
                    b_at[x] = j
                    break
        # Extend the chain from end x - 1 to end x
        new_chain = [(nums[x], x)]
        for v, j in chain:
            nv = gcd(nums[x], v)
            if nv != new_chain[-1][0]:
                new_chain.append((nv, j))
        chain = new_chain

    # Option: remove nothing. Valid splits are a .. b - 1
    G = pre[n - 1]
    best = max(0, last[G] - first[G])

    # Options: remove index x. The score is the number of valid splits b - a
    for x in range(n):
        cnt = b_at[x] - a_at[x]
        if cnt > best:
            best = cnt
    return best
